SELECT COUNT(*) AS available_vehicles
FROM vehicles
WHERE status = 'available';

SELECT COUNT(*) AS total_toyota_cars
FROM vehicles
WHERE make = 'Toyota';

SELECT make, model, license_plate
FROM vehicles
WHERE status = 'maintenance';

SELECT SUM(amount) AS total_revenue
FROM payments
WHERE status = 'completed';

SELECT maintenance_type, SUM(cost) AS total_cost
FROM maintenance_records
GROUP BY maintenance_type;

SELECT make, model, daily_rate
FROM vehicles
WHERE daily_rate > (SELECT AVG(daily_rate) FROM vehicles);

SELECT * 
FROM vehicles 
WHERE status = 'available';

SELECT AVG(total_revenue) AS average_revenue_per_client
FROM (
    SELECT r.client_id, SUM(r.total_cost) AS total_revenue
    FROM reservations r
    GROUP BY r.client_id
) AS client_revenue;

SELECT COUNT(*) AS total_rentals
FROM reservations
WHERE pickup_date >= date('now', '-1 month');
